<?php use function KB\{e,url,post}; use KB\Security; ?>
<section class="auth-layout"><div class="auth-story"><span class="eyebrow">THERE’S A PLACE FOR YOU HERE</span><h1>Start small.<br><em>Grow deep.</em></h1><p>Join a community exploring the Bible, one thoughtful question at a time.</p><span class="story-reference">YOUR JOURNEY IS JUST BEGINNING.</span></div><div class="panel auth-panel"><h2>Create your account.</h2><p class="muted">A few details, and you’re on your way.</p><?php if($error): ?><div class="notice error" role="alert"><?= e($error) ?></div><?php endif; ?><?php if($notice): ?><div class="notice success" role="status"><?= e($notice) ?> <a href="<?= e(url('login')) ?>">Return to sign in.</a></div><?php endif; ?><?php $mode='register'; require __DIR__.'/_google.php'; ?><form class="stack" method="post"><?= Security::csrfField() ?><label>Full name<input name="name" value="<?= e(post('name')) ?>" required minlength="2" maxlength="120" autocomplete="name"></label><label>Email address<input type="email" name="email" value="<?= e(post('email')) ?>" required maxlength="190" autocomplete="email"></label><div class="form-grid"><label>Password<input type="password" name="password" minlength="12" maxlength="72" required autocomplete="new-password"></label><label>Confirm password<input type="password" name="password_confirm" minlength="12" maxlength="72" required autocomplete="new-password"></label></div><small class="muted">Use at least 12 characters. A unique passphrase is best.</small><label class="check-label"><input type="checkbox" name="accept" value="1" required> I agree to use this community respectfully and understand that my learning progress is visible to its administrators.</label><button class="button full">Create account <span aria-hidden="true">↗</span></button></form><p class="form-footer">Already part of the community? <a href="<?= e(url('login')) ?>">Sign in</a></p></div></section>
